output.arguments:
{"command":"set -o pipefail
for args in "" "--help" "-h" "--version" "-V"; do
  printf '\n### ./executable %s\n' "$args"
  ./executable $args >out.tmp 2>err.tmp; rc=$?; printf 'rc=%s\n-- stdout --\n' "$rc"; sed -n '1,160p' out.tmp; printf -- '-- stderr --\n'; sed -n '1,160p' err.tmp; 
done
rm -f out.tmp err.tmp"}
